'use client';

import { useActionState } from 'react';

async function submitContactForm(prevState: any, formData: FormData) {
  'use server';

  const name = formData.get('name');
  const email = formData.get('email');
  const message = formData.get('message');

  // Validation: Check that all fields are provided
  if (!name || typeof name !== 'string' || name.trim() === '') {
    return { success: false, error: 'Name is required' };
  }

  if (!email || typeof email !== 'string' || email.trim() === '') {
    return { success: false, error: 'Email is required' };
  }

  if (!message || typeof message !== 'string' || message.trim() === '') {
    return { success: false, error: 'Message is required' };
  }

  // Here you would typically save to a database
  console.log('Contact form submitted:', { name, email, message });

  return { success: true, error: null };
}

export default function ContactForm() {
  const [state, formAction, isPending] = useActionState(submitContactForm, { success: false, error: null });

  return (
    <div>
      <h2>Contact Us</h2>
      <form action={formAction}>
        <div style={{ marginBottom: '1rem' }}>
          <label htmlFor="name">
            Name:
            <input
              type="text"
              id="name"
              name="name"
              required
              style={{ marginLeft: '0.5rem', padding: '0.25rem' }}
            />
          </label>
        </div>

        <div style={{ marginBottom: '1rem' }}>
          <label htmlFor="email">
            Email:
            <input
              type="email"
              id="email"
              name="email"
              required
              style={{ marginLeft: '0.5rem', padding: '0.25rem' }}
            />
          </label>
        </div>

        <div style={{ marginBottom: '1rem' }}>
          <label htmlFor="message">
            Message:
            <textarea
              id="message"
              name="message"
              required
              rows={4}
              style={{ marginLeft: '0.5rem', padding: '0.25rem', display: 'block', marginTop: '0.25rem' }}
            />
          </label>
        </div>

        <button type="submit" disabled={isPending} style={{ padding: '0.5rem 1rem' }}>
          {isPending ? 'Submitting...' : 'Submit'}
        </button>

        {state.error && (
          <div style={{ marginTop: '1rem', color: 'red' }}>
            {state.error}
          </div>
        )}

        {state.success && !state.error && (
          <div style={{ marginTop: '1rem', color: 'green' }}>
            Message sent successfully!
          </div>
        )}
      </form>
    </div>
  );
}

